// Match against the OPTIMISED CV when one exists - that is the whole point of
// putting the review and rewrite in front of the matching. Fall back to the
// original upload if the rewrite has not happened yet.

const cfg = $('Config').first().json;
const state = ($input.first().json || {}).state || {};

const name = state.cv_optimised_name || state.cv_name;
if (!name) {
  throw new Error('No CV on file yet. Send a CV to Rafid before asking for work.');
}

return [{
  json: {
    cv_file: name,
    used_optimised: Boolean(state.cv_optimised_name),
    bridge: cfg.bridge,
    top_k: cfg.top_k,
    mode: cfg.mode,
  },
}];

// Carry-over fix #8: never trust an LLM's shape. Week 6 saw a valid HTTP 200
// carrying JSON truncated at exactly 4096 tokens.

let raw = $input.first().json.text ?? $input.first().json.output ?? '';
raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();

let p;
try {
  p = JSON.parse(raw);
} catch (e) {
  throw new Error('Profile step did not return valid JSON. First 300 chars: ' + raw.slice(0, 300));
}

if (!Array.isArray(p.core_skills) || p.core_skills.length === 0) {
  throw new Error('Profile has no core_skills - refusing to match on an empty profile.');
}
if (!Array.isArray(p.notable_projects) || p.notable_projects.length === 0) {
  // Not fatal, but the pitches will be weaker - this is exactly the Week 6 bug.
  p.notable_projects = [];
}

const prev = $('Pick CV').first().json;
return [{ json: { ...prev, profile: p, profile_json: JSON.stringify(p) } }];

// Carry-over fix #5: the API exposes `language`, and roughly 7 of 50 projects
// come back in another language. One filter, deliberately skipped in Week 6.

const res = $input.first().json;
const projects = (res.result && res.result.projects) || [];

const out = [];
for (const p of projects) {
  if ((p.language || '').toLowerCase() !== 'en') continue;

  const b = p.budget || {};
  const cur = (p.currency || {}).code || '';
  out.push({
    json: {
      job_id: String(p.id),
      title: p.title || '',
      description: String(p.preview_description || '').slice(0, 600),
      budget_min: b.minimum ?? '',
      budget_max: b.maximum ?? '',
      currency: cur,
      skills: (p.jobs || []).map((j) => j.name).join(', '),
      url: p.seo_url ? ('https://www.freelancer.com/projects/' + p.seo_url) : '',
      language: p.language || '',
      fetched_at: new Date().toISOString().slice(0, 16).replace('T', ' '),
    },
  });
}

if (out.length === 0) throw new Error('Freelancer returned no English projects.');
return out;

// FR-31: a job already sent is never sent again. This is what stops the daily
// digest repeating itself, so it is checked BEFORE scoring, not after.
//
// Read Sent Matches is a Sheets node, so $json here is sheet rows - the fresh
// jobs have to be pulled from their own node by name (R-19).

const fresh = $('Normalise and Filter').all().map((i) => i.json);

const sent = new Set(
  $input.all()
    .map((i) => String((i.json || {}).job_id || '').trim())
    .filter(Boolean)
);

const unseen = fresh.filter((j) => !sent.has(String(j.job_id)));

if (unseen.length === 0) {
  // Deliberately not an error: "nothing new today" is a valid outcome (FR-32).
  return [{ json: { __empty: true, reason: 'every fetched project has already been sent' } }];
}

return unseen.map((j) => ({ json: j }));

// Validate, then rank. Carry-over fix #8 again.

let raw = $input.first().json.text ?? $input.first().json.output ?? '';
raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();

let scored;
try {
  scored = JSON.parse(raw);
} catch (e) {
  throw new Error('Scoring step did not return valid JSON. First 300 chars: ' + raw.slice(0, 300));
}
if (!Array.isArray(scored) || scored.length === 0) {
  throw new Error('Scoring step returned no usable array.');
}

const jobs = $('Bundle Jobs').first().json.jobs;
const byId = new Map(jobs.map((j) => [String(j.job_id), j]));

const merged = scored
  .map((s) => {
    const j = byId.get(String(s.job_id));
    if (!j) return null;                       // hallucinated id - drop it
    return { ...j, score: Number(s.score) || 0, reason: s.reason || '' };
  })
  .filter(Boolean);

if (merged.length === 0) {
  throw new Error('Scoring returned ids that match none of the fetched projects.');
}

const asked = Number($('Parse Profile').first().json.top_k) || 5;
const k = Math.min(Math.max(asked, 1), 10);   // a typo must not ask for 900

merged.sort((a, b) => b.score - a.score);
return [{ json: { top: merged.slice(0, k), total_scored: merged.length, k } }];

// Validate the pitches, then check the carry-over fix actually held: every
// pitch must cite a real project, and none may contain the Week 6 filler.

let raw = $input.first().json.text ?? $input.first().json.output ?? '';
raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();

let pitches;
let truncated = false;

try {
  pitches = JSON.parse(raw);
} catch (e) {
  // Carry-over #8: the response was cut off mid-JSON. Salvage the objects that
  // did complete rather than losing all five because the last one was clipped.
  truncated = true;
  const re = /"job_id"\s*:\s*"?([^",}]+)"?\s*,\s*"pitch"\s*:\s*"((?:[^"\\]|\\.)*)"/g;
  pitches = [];
  let m;
  while ((m = re.exec(raw)) !== null) {
    pitches.push({ job_id: m[1], pitch: m[2].replace(/\\"/g, '"') });
  }
  if (pitches.length === 0) {
    throw new Error('Pitch step returned unparseable JSON and nothing could be salvaged. First 300 chars: ' + raw.slice(0, 300));
  }
}

if (!Array.isArray(pitches)) {
  throw new Error('Pitch step did not return an array.');
}

const top = $('Rank Top K').first().json.top;
const byId = new Map(pitches.map((p) => [String(p.job_id), p.pitch || '']));

const BANNED = [
  'deliver a high-quality solution', 'meets your requirements', 'i am excited',
  'passionate', 'extensive experience', 'proven track record',
];
const projects = ($('Parse Profile').first().json.profile.notable_projects || [])
  .map((p) => String(p.name || '').toLowerCase())
  .filter(Boolean);

const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');
const mode = $('Parse Profile').first().json.mode || 'on-request';

return top.map((j, i) => {
  const pitch = byId.get(String(j.job_id)) || '';
  const low = pitch.toLowerCase();
  return {
    json: {
      rank: i + 1,
      job_id: j.job_id,
      title: j.title,
      url: j.url,
      score: j.score,
      reason: j.reason,
      pitch,
      budget: [j.budget_min, j.budget_max].filter(Boolean).join(' - ') + ' ' + (j.currency || ''),
      // Reported, not enforced: Day 4 checks these rather than failing a live run.
      cites_project: projects.some((n) => n && low.includes(n)),
      has_banned_phrase: BANNED.some((b) => low.includes(b)),
      pitch_missing: pitch.length === 0,
      response_was_truncated: truncated,
      source: mode,
      sent_at: stamp,
    },
  };
});

// What the calling workflow receives.
const items = $('Parse Pitches').all().map((i) => i.json);
return [{ json: {
  ok: true,
  count: items.length,
  used_optimised_cv: $('Parse Profile').first().json.used_optimised === true,
  matches: items,
} }];

// FR-32: having nothing to say is a valid outcome and must be said out loud.
// A digest that goes quiet is indistinguishable from a digest that is broken.
return [{ json: {
  ok: true,
  count: 0,
  matches: [],
  reason: $input.first().json.reason || 'no new projects',
} }];
